window.REPORT_PRELOAD_CACHE["CNC.html"] = {"version":"3adcad1fcdc8cd0716167bfee55b492ee09a820360f198c47c9af1671f6786b0","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>森特金 (Centene Corporation NYSE: CNC) 深度研究报告：美国 Medicaid 龙头、Managed Care 巨头与价值重估复利引擎</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n cncpurple: {\n 300: '#D8B4FE',\n 400: '#C084FC',\n 500: '#9333EA',\n 600: '#7E22CE',\n 700: '#6B21A8',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n teal: {\n 400: '#22D3EE',\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n /* 自定义滚动条与机构研报细节排版 */\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n /* 打印友好优化 */\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n /* 卡片悬浮微光与上移过渡 */\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n /* 侧边导航激活态：森特金高贵紫渐变色 */\n .nav-link.active {\n background: linear-gradient(90deg, rgba(147, 51, 234, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #9333EA;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-cncpurple-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-cncpurple-600 via-cncpurple-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-cncpurple-400 to-cncpurple-600 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n CNC\n </div>\n <div>\n <div class=\"text-[11px] text-cncpurple-400 font-semibold tracking-wider uppercase\">NYSE: CNC · Managed Care</div>\n <div class=\"text-sm font-bold leading-tight\">森特金 Centene 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">CNC 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3.5 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 全球托管医疗巨头横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与复利推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球医疗健康与托管医疗研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / FY26E)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <!-- 机构品牌头 -->\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-cncpurple-400 via-cncpurple-500 to-cncpurple-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-cncpurple-500/25\">\n CNC\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-cncpurple-400 bg-cncpurple-500/15 px-2 py-0.5 rounded\">NYSE: CNC</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">森特金深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 美国 Medicaid 托管医疗霸主 · 盈利修复周期与低估值价值重估标的\n </p>\n </div>\n\n <!-- 股票实时快照徽章 -->\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$35.40 <span class=\"text-slate-400 text-[10px]\">($30.1-$48.2)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">2026E 调整后 EPS</span>\n <span class=\"font-mono font-bold text-emerald-400\">$6.80–$7.00 <span class=\"text-slate-400\">(+12%)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">远期市盈率 (P/E)</span>\n <span class=\"font-mono font-bold text-cncpurple-400\">~5.1x P/E · 严重低估</span>\n </div>\n </div>\n\n <!-- 七大核心章节目录导航 -->\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-cncpurple-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>全球托管医疗巨头横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与复利推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <!-- 侧边栏底部工具栏 -->\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-cncpurple-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-cncpurple-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-br from-cncpurple-500 to-cncpurple-600 hover:from-cncpurple-600 hover:to-cncpurple-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <!-- 顶部研报元数据标签栏 -->\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-cncpurple-500/15 text-cncpurple-700 dark:text-cncpurple-400 font-bold border border-cncpurple-500/30\">评级：强烈买入 / 极端低估修复标的</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026 医疗保费重置与 Medicaid 重新确定资格（Redetermination）消化期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: CNC</span>\n </div>\n </div>\n\n <!-- Hero 标题卡片 -->\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <!-- 背景高贵紫点阵纹理 -->\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#9333EA 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-cncpurple-500/20 border border-cncpurple-400/40 text-cncpurple-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-cncpurple-400 animate-pulse\"></span>\n <span>CORE THESIS · 全美第一大 Medicaid 托管医疗霸主 × ~5.1x 极度折价 P/E × 州级费率重置（Rate Adequacy）与 MLR 利润修复</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 森特金 Centene Corporation (NYSE: CNC) 深度研究报告：美国 Medicaid 托管医疗霸主、医疗保险巨头与极端低估值价值重估复利引擎\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 森特金（Centene）作为全美最大的 <strong class=\"text-white\">Medicaid（医疗救助）托管医疗服务商</strong>，在经历全美医疗补助重新确定资格（Redetermination）及行业整体医疗利用率（Medical Loss Ratio, MLR）上升的周期阵痛后，正迎来强劲的<strong class=\"text-cncpurple-300\">州级保费费率充分重置（Rate Adequacy）</strong>与盈利修复拐点。公司 2026 财年营收预计超 <strong class=\"text-white\">$1,500B</strong>，调整后 EPS 锚定在 <strong class=\"text-emerald-400\">$6.80–$7.00</strong> 区间。\n 然而受行业悲观预期拖累，其当前动态 P/E 仅约 <strong class=\"text-cncpurple-400\">~5.1x</strong>，与其千亿级顶尖医疗保险巨头的地位严重背离，构筑起美股医疗板块罕见的深度价值与困境反转（Turnaround）配置良机。\n </p>\n\n <!-- 核心投资结论高亮条 -->\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">全美第一大 Medicaid 霸主</div>\n <div class=\"text-white font-semibold\">服务超 2,600 万名政府与商业医疗会员，在低收入与政府健康保障领域无可替代</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">极端低估的估值安全垫</div>\n <div class=\"text-cncpurple-400 font-semibold\">远期市盈率仅 ~5.1x P/E，远低于历史均值及同行（UNH / ELV），下行风险几近出清</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">州级费率重置推动 MLR 改善</div>\n <div class=\"text-emerald-400 font-semibold\">各州 Medicaid 签约费率逐步匹配真实医疗成本，医疗损失率（MLR）重回健康下行通道</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <!-- KPI 1 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总市值与最新股价</span>\n <span class=\"p-1.5 rounded-lg bg-cncpurple-500/15 text-cncpurple-600 dark:text-cncpurple-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$18.9B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$35.40</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 估值经历非理性杀跌后处于历史极低分位，市值远低于其超千亿美元的年营业收入规模。\n </p>\n </div>\n\n <!-- KPI 2 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>2026E 调整后 EPS 预期</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$6.80–$7.00</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+12% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 随着州级 Medicaid 费率补偿逐步到位，盈利能力展现出强劲的逐季修复态势。\n </p>\n </div>\n\n <!-- KPI 3 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总医疗服务会员人数</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~26.5M</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/15 px-2 py-0.5 rounded\">全美顶尖规模</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 拥有超过 2,650 万名医疗保险会员，覆盖 Medicaid、Medicare 及 Marketplace 商业健康险。\n </p>\n </div>\n\n <!-- KPI 4 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>远期市盈率 (Forward P/E)</span>\n <span class=\"p-1.5 rounded-lg bg-cncpurple-500/15 text-cncpurple-600 dark:text-cncpurple-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~5.1x</span>\n <span class=\"text-xs font-bold text-cncpurple-700 dark:text-cncpurple-400 bg-cncpurple-500/15 px-2 py-0.5 rounded\">历史罕见折价</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 相比医疗保险行业 15-20x 的平均估值，CNC 展现出极大的估值修复弹性与潜在爆发空间。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务与收入架构 (Business & Revenue Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-cncpurple-600 dark:text-cncpurple-400\">Section 01 · Business & Revenue Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：Medicaid 医疗救助为主体，Medicare 与 Marketplace 双翼齐飞</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">全年总营收 ~$155B+ · 政府资助医疗占比超 85%</span>\n </div>\n\n <!-- 交互式 Chart.js 双视图切换面板 -->\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <!-- 左侧：双视图图表 -->\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2023–2026E 总营收规模与三大保险板块结构</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">Medicaid 构成核心基本盘，Commercial Marketplace 与 Medicare 稳步扩张</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-cncpurple-600 dark:text-cncpurple-400 shadow-sm transition cursor-pointer\">视图A：营收演进与总规模</button>\n <button onclick=\"switchBizChart('segments')\" id=\"btn-chart-seg\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：业务线会员权重分布</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <!-- 右侧：结构性拆解核心洞察 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">三大核心保险业务矩阵</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-cncpurple-500/15 text-cncpurple-600 dark:text-cncpurple-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Medicaid（医疗救助/政府托管健康险）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 全美规模第一的 Medicaid 托管服务商。通过与各州政府深度签约，为低收入群体、儿童及残障人士提供全方位医疗保障，贡献集团过半数的总保费收入。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Commercial Marketplace（平价法案商业健康险）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 凭借 Ambetter 品牌稳居全美 ACA（平价医疗法案）Exchange 市场龙头地位，近年来受益于参保人数持续打破纪录而实现高质量高速增长。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Medicare（老年医疗保险与长者健康护理）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 专注于 Medicare Advantage（MA）及辅助服务，伴随美国老龄化浪潮加速推进，成为公司中长期重点发力的利润增长点。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">核心业务支柱</span>\n <span class=\"font-bold text-cncpurple-600 dark:text-cncpurple-400\">Medicaid 龙头地位与 Marketplace 强劲扩张</span>\n </div>\n </div>\n </div>\n\n <!-- 四大业务资产分部详细卡片矩阵 -->\n <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5\">\n <!-- 分部 1：Medicaid 托管医疗 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-cncpurple-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-cncpurple-500/15 text-cncpurple-700 dark:text-cncpurple-400 text-xs font-bold\">全美第一 · 核心基本盘</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">数千万参保人</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">1. Medicaid 托管医疗</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 作为各州政府不可或缺的医疗保障外包伙伴，经历 Redetermination 资格重核周期后，正迎来各州充分补偿医疗通胀的费率重置红利。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n 州级费率重置 · 利润率触底回升\n </div>\n </div>\n\n <!-- 分部 2：Commercial Marketplace -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-700 dark:text-teal-400 text-xs font-bold\">高速增长 · Ambetter品牌</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">ACA 市场龙头</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. Commercial Marketplace</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Ambetter 个人健康险品牌覆盖全美众多州。凭借高性价比与广泛的网络布局，在平价法案交易所中持续吸纳高质健康会员。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n 参保人数连创新高 · 现金流健康\n </div>\n </div>\n\n <!-- 分部 3：Medicare 老年医保 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">老龄化红利 · 战略拓展</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">MA 优质布局</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. Medicare 业务群</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 针对美国庞大老龄化群体推出的 Medicare Advantage 计划。公司通过精细化星级评级管理与医疗护理协同，不断提升该板块盈利质量。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold\">\n 应对老龄化浪潮 · 利润潜力巨大\n </div>\n </div>\n\n <!-- 分部 4：药房福利管理与专科医疗 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-700 dark:text-indigo-400 text-xs font-bold\">协同闭环 · Envolve</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">PBM 与专科服务</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. 药房福利与专科医疗服务</h3>\n <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 通过 Envolve 药房福利管理（PBM）及专科医疗服务网络，有效控制会员用药成本，与医疗保险形成紧密的业务协同与成本控制闭环。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n 控费闭环 · 提升整体医疗效率\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与四重核心护城河 (Industry Position & Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：Medicaid 规模壁垒、州级政企关系与精细化风控</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 美国政府赞助健康险无可替代的压舱石)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <!-- 左侧：四重护城河深度解析 -->\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <!-- 护城河 1 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-cncpurple-500/15 text-cncpurple-600 dark:text-cncpurple-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全美第一大 Medicaid 会员规模与网络</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 作为全美服务 Medicaid 会员最多的托管医疗机构，森特金在与各州卫生部门的议价、医疗服务网络（医院与医生）覆盖上拥有无可匹敌的规模效应与成本摊薄优势。\n </p>\n </div>\n\n <!-- 护城河 2 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">深厚的州级政企关系与合规壁垒</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 政府资助健康险（Government-Sponsored Healthcare）涉及极其复杂的州级法规与合规审计。CNC 历经数十年的属地化深耕，与各州政府建立起极高的信任与准入壁垒。\n </p>\n </div>\n\n <!-- 护城河 3 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">多元化收入来源（Medicaid + Marketplace + Medicare）</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 业务不仅局限于 Medicaid，更通过 Ambetter 在 ACA 商业健康险市场占据龙头地位，有效分散了单一政府项目的政策波动与预算调整风险。\n </p>\n </div>\n\n <!-- 护城河 4 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">强大的精细化医保控费与 MLR 管理能力</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 面对医疗利用率上升周期，公司通过强化医疗管理（Medical Management）、严格的 PBM 控费及与各州谈判费率重置，持续修复并优化医疗损失率（MLR）。\n </p>\n </div>\n </div>\n\n <!-- 右侧：五维护城河雷达图 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">托管医疗与健康险五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">森特金 (CNC) vs 传统综合健康险巨头 (UNH/ELV)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 全球托管医疗巨头横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-cncpurple-600 dark:text-cncpurple-400\">Section 03 · Managed Care Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 全球托管医疗巨头横向对比：Medicaid 专业专精 vs 综合医疗帝国</h2>\n </div>\n <!-- 交互式筛选按钮 -->\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-cncpurple-500 text-white shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('government')\" data-filter=\"government\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">政府资助医疗专精龙头</button>\n <button onclick=\"filterCompetitors('diversified')\" data-filter=\"diversified\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">多元化综合医疗巨头</button>\n </div>\n </div>\n\n <!-- 横向对比矩阵表格 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与核心代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心业务与强项领域</th>\n <th class=\"py-4 px-4 min-w-[140px]\">市值与估值特征 (P/E)</th>\n <th class=\"py-4 px-4 min-w-[115px]\">营收规模 (FY)</th>\n <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <!-- 行 1：森特金 CNC 基准 -->\n <tr data-category=\"government\" class=\"bg-cncpurple-500/5 dark:bg-cncpurple-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-cncpurple-500 text-white text-[10px] font-extrabold\">Medicaid 霸主</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">森特金 Centene (CNC)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Medicaid / Ambetter Marketplace</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">全美第一大 Medicaid 与 ACA 商业健康险</td>\n <td class=\"py-4 px-4 font-mono font-bold text-cncpurple-600 dark:text-cncpurple-400\">市值 ~$18.9B · ~5.1x P/E (极度低估)</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~$155B+</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>极致价值重估标的：</strong>由于前期医疗利用率上升受压，估值杀至历史冰点 (~5x P/E)；随着州级费率充分重置，盈利弹性与估值修复空间全行业最大。\n </td>\n </tr>\n\n <!-- 行 2：联合健康 UNH -->\n <tr data-category=\"diversified\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">联合健康集团 UnitedHealth (UNH)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Optum 医疗服务 + UnitedHealthcare</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">商保、Medicare、Optum 健康服务与IT</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">全球最大医疗巨头 · 较高 P/E</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~$400B+</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全球医疗绝对图腾：</strong>Optum 医疗服务闭环无敌，盈利极具稳健性，但市值庞大使成长弹性相对受限。\n </td>\n </tr>\n\n <!-- 行 3：Elevance Health (ELV) -->\n <tr data-category=\"diversified\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Elevance Health (ELV)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">原 Anthem / 蓝十字蓝盾最大持牌人</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">商业健康险、Medicaid、Carelon 服务</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">全美第二大商业健康险巨头</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~$170B+</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>商业商保与蓝十字网络优势：</strong>在商业健康险与多元化医疗服务上实力雄厚，同样经历近期医疗成本波动后的估值修复期。\n </td>\n </tr>\n\n <!-- 行 4：Molina Healthcare (MOH) -->\n <tr data-category=\"government\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">莫利纳医疗 Molina Healthcare (MOH)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">政府资助医疗专精同行</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Medicaid、Medicare 与 Marketplace</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">中型政府医疗专业户</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~$15B+</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>纯正政府医保标的：</strong>业务结构与 CNC 高度重合，专注于低收入政府健康保障，同样受益于州级费率重置周期。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <!-- 配套 Chart.js 横向条形图：估值与营收规模对比 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要托管医疗与健康险巨头远期市盈率（Forward P/E）横向对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">森特金 (CNC) 远期 P/E 仅约 5.1x，在全行业中呈现出极具吸引力的极端价值洼地</p>\n </div>\n <span class=\"text-xs font-semibold text-cncpurple-700 dark:text-cncpurple-400 bg-cncpurple-500/15 px-2.5 py-1 rounded\">5.1x P/E 全行业最低估值洼地</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与复利推演 (Financial Health & Compounding Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Compounding Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：千亿级营收支撑与估值回归复利推演</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">2026E 营收 ~$155B+ · EPS 锚定 $6.80–$7.00</span>\n </div>\n\n <!-- 1. 财务健康度四大硬核指标卡 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-cncpurple-600 dark:text-cncpurple-400 uppercase\">Annual Revenue</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$155B+</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 全年营业收入稳定在 1,500 亿美元以上巨型体量，体现出极强的国民卫生健康保障承载力。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Adjusted EPS (2026E)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$6.80–$7.00</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 随着州级 Medicaid 费率充分到位，调整后每股收益预计实现约 12% 的稳健双位数增长。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Medical Loss Ratio (MLR)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">逐步优化改善</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 医疗损失率在经历行业性波动后，伴随各州费率重置正逐步返回健康的目标管理区间。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Valuation Disconnect</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~5.1x P/E</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 当前市价对应 2026E EPS 的 P/E 仅约 5.1x，估值修复潜力巨大，戴维斯双击可期。\n </p>\n </div>\n </div>\n\n <!-- 2. 交互式 Chart.js 双轴演进图 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2023–2026E 营业收入规模与调整后 EPS 稳步复苏趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">千亿营收基本盘稳如磐石，伴随费率重置与控费优化，EPS 触底回升至 $6.80–$7.00 区间</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-cncpurple-700 dark:text-cncpurple-400 bg-cncpurple-500/15 px-2.5 py-1 rounded\">2026E EPS $6.80–$7.00</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <!-- 3. 交互式组件：森特金（CNC）多维复利与估值重估动态推演器 -->\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-cncpurple-400 font-bold\">\n <span>VALUATION RE-RATING & COMPOUNDING ENGINE · 估值重估与复利模拟器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">森特金 (CNC) 投资回报与估值修复（Re-rating）动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 $35.40 | 2026E 调整后 EPS 中枢 $6.90（起始 P/E ~5.1x）| 支持自由调节预期 EPS 增速与未来估值锚</p>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <!-- 左侧参数控制区 -->\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <!-- 本金滑块 -->\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始投资本金 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateCompSimulator()\" class=\"w-full accent-[#9333EA] cursor-pointer\">\n </div>\n\n <!-- 年限滑块 -->\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">3 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"3\" oninput=\"updateCompSimulator()\" class=\"w-full accent-[#9333EA] cursor-pointer\">\n </div>\n\n <!-- EPS 复合增速滑块 -->\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">预期年化 EPS 复合增长率 (CAGR)</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">12.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"5\" max=\"25\" step=\"1\" value=\"12\" oninput=\"updateCompSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <!-- 目标退出 P/E 估值锚滑块 -->\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">期末目标退出估值倍数 (Forward P/E)</span>\n <span id=\"sim-pe-label\" class=\"font-mono font-bold text-cncpurple-400 text-sm\">10.0x (行业修复中枢)</span>\n </div>\n <input id=\"sim-pe\" type=\"range\" min=\"6\" max=\"15\" step=\"0.5\" value=\"10\" oninput=\"updateCompSimulator()\" class=\"w-full accent-[#C084FC] cursor-pointer\">\n </div>\n </div>\n\n <!-- 右侧四大实时测算结果卡片 -->\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计总资产市值</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$59,850</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +99.5% (戴维斯双击)</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末对应隐含股价 ($/股)</div>\n <div id=\"sim-implied-price\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-cncpurple-400 mt-1.5\">$70.52</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">基于期末 EPS 与目标 P/E 乘积</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">隐含复合年化回报率 (CAGR)</div>\n <div id=\"sim-cagr\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">25.8%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">兼具业绩增长与估值修复双重爆发力</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末对应 EPS 绝对值 ($/股)</div>\n <div id=\"sim-end-eps\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">$7.05</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">起始 EPS $6.90 经复合增长后</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4. 华尔街多空核心分歧对比 -->\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">极度低估 + 费率重置</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>5.x倍 P/E 带来极宽安全边际：</strong>市场过度计入了 Medicaid 会员波动与前期 MLR 压力，股价反应过度，具备极强的困境反转（Turnaround）爆发力。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>州级费率重置（Rate Adequacy）刚性兑现：</strong>各州政府已充分意识到医疗通胀压力，相继批准足额的 Medicaid 费率上调，直接驱散盈利阴霾。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Marketplace 商业健康险持续超预期：</strong>Ambetter 品牌在 ACA 交易所虹吸大量参保用户，成为高质量增长的稳定现金流来源。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">医疗利用率波动</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>医疗利用率（Medical Utilization）反复不确定性：</strong>若会员就医意愿与高昂专科药物支出超预期上升，可能再次挤压短期 MLR 利润率空间。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>Medicaid 参保总人数结构性缩减：</strong>随着红利期后各州持续推进资格重核，总参保会员数可能较疫情高峰期出现自然回落。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>政府资助医疗政策敏感度高：</strong>公司重度依赖联邦与州级财政预算，政策端任何微调均可能对板块情绪造成阶段性压制。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-cncpurple-600 dark:text-cncpurple-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与医疗板块配置纪律</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：医疗健康组合中的极端低估值困境反转核心标的</span>\n </div>\n\n <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <!-- 牛市情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：30%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">12.0x–14.0x P/E ($85–$98)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>各州 Medicaid 费率补偿力度超预期，MLR 降至历史最优水平，EPS 连续数年超预期增长，市场给予其正常化 12x+ P/E 估值重修复。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 潜在上行空间：+140% 至 +175% (戴维斯双击)\n </div>\n </div>\n\n <!-- 基准情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-cncpurple-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-cncpurple-500/15 text-cncpurple-700 dark:text-cncpurple-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-cncpurple-600 dark:text-cncpurple-400\">概率：55%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">9.0x–11.0x P/E ($62–$75)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>2026E EPS 稳健达成 $6.80–$7.00 目标，市场情绪逐步从恐慌转向理性，估值缓慢向 10x 行业均值理性回归。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-cncpurple-600 dark:text-cncpurple-400\">\n 潜在上行空间：+75% 至 +110% (盈利增长+估值双修复)\n </div>\n </div>\n\n <!-- 熊市情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：15%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防御估值：4.5x–5.0x P/E ($30–$35)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>医疗利用率长期高位粘滞导致 MLR 持续超标，州级费率重置严重滞后于真实成本，估值维持冰点震荡。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在下行回撤：-10% 至 -15% (已处于当前股价安全垫附近)\n </div>\n </div>\n </div>\n\n <!-- 2. 四大核心风险评估矩阵 -->\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险评估与机构跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 医疗利用率（Medical Utilization）居高不下</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">会员就医频次与专科医疗支出超预期反弹</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 随着参保会员就医意愿全面恢复及高昂的手术、专科门诊需求释放，若医疗损失率（MLR）未能如期回落，将直接对单季净利润构成阶段性压制。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 州级 Medicaid 费率重置滞后风险</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">部分州财政预算紧张导致保费补偿不到位</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管多数州已积极推进费率重置，但仍有部分州由于地方财政压力，对 Medicaid 托管机构的费率上调审批存在时间差或幅度打折。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-700 dark:text-indigo-400 text-xs font-bold\">03 · 政府医保政策与资格重核变动</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">Medicaid 资格重核（Redetermination）后续尾声扰动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 资格重核虽然接近尾声，但期间会员流失率的变化及部分合规会员未能及时重新登记，仍可能造成参保总人数出现结构性波动。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-700 dark:text-teal-400 text-xs font-bold\">04 · 医疗保险行业整体情绪压制</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">宏观医疗板块监管与同业估值拖累</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 华尔街对整体 Managed Care 板块的医疗成本担忧可能形成板块共振，短期内可能延缓极低估值向合理中枢回归的催化节奏。\n </p>\n </div>\n </div>\n </div>\n\n <!-- 3. 机构级组合配置纪律横幅 -->\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-cncpurple-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与困境反转策略建议</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 极端低估安全边际（5.1x P/E）</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 在当前 5.x 倍远期市盈率下，CNC 的下行风险已被股价大幅消化；其千亿级营收与全美第一大 Medicaid 霸主地位赋予其极高的安全边际与不对称上行回报。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-cncpurple-400 mb-1\">2. 费率重置催化下的戴维斯双击</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 随着各州 Medicaid 费率充分补偿医疗通胀，MLR 改善将直接驱动 EPS 超预期，引发“业绩+估值倍数”双升的戴维斯双击行情。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 渐进式左侧布局纪律</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 建议在成长与防御组合中将其作为<strong>深度价值（Deep Value）困境反转标的</strong>进行左侧逢低布局，静待医疗板块情绪均值回归。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六: 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-cncpurple-500/15 text-cncpurple-700 dark:text-cncpurple-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续校验森特金的盈利修复与估值重估逻辑：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <!-- KPI 1 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#9333EA] focus:ring-cncpurple-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 医疗损失率（MLR）是否如期重回健康管理区间</span>\n <span class=\"text-[11px] font-mono text-cncpurple-600 dark:text-cncpurple-400 font-semibold shrink-0\">盈利核心底线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控各季财报公布的综合 MLR，确认医疗成本上升势头得到有效控制并呈现边际改善。\n </p>\n </div>\n </label>\n\n <!-- KPI 2 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#9333EA] focus:ring-cncpurple-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 州级 Medicaid 费率重置（Rate Adequacy）谈判落地情况</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">费率补偿驱动</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估核心运营州（如得州、佛州等）对 Medicaid 承包费率的调升幅度是否充分覆盖医疗通胀。\n </p>\n </div>\n </label>\n\n <!-- KPI 3 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#9333EA] focus:ring-cncpurple-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 2026E 调整后 EPS 指引（$6.80–$7.00）达成与上修</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">年度盈利锚点</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 追踪每季实际实现的摊薄 EPS 是否稳步处于或超越指引区间中枢。\n </p>\n </div>\n </label>\n\n <!-- KPI 4 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#9333EA] focus:ring-cncpurple-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. Commercial Marketplace (Ambetter) 参保会员保持高质量扩张</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">商业健康险增量</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控 ACA 交易所业务的会员净增数与风险池健康度，确保商保板块持续贡献稳健毛利。\n </p>\n </div>\n </label>\n\n <!-- KPI 5 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#9333EA] focus:ring-cncpurple-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 运营费用率（SG&A Expense Ratio）持续精简优化</span>\n <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">费用纪律与杠杆</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 考察管理层在行政、IT及运营开支上的费用控制力度，验证百亿级体量下的规模化降本成效。\n </p>\n </div>\n </label>\n\n <!-- KPI 6 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#9333EA] focus:ring-cncpurple-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 股份回购授权执行与资产负债表杠杆率安全边际</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">资本配置与回购</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 关注公司在极端低估市价下利用自由现金流开展股份回购的实际执行力度及对 EPS 的增厚倍数。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 页脚免责声明 (Disclaimer Footer)\n ========================================================= -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>森特金 Centene Corporation (NYSE: CNC) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：2026Q3 财报及 2026 年 11 月市场一致预期 (FY26E)</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于森特金公开财务报告（10-Q/10-K）、2026Q3 业绩电话会议披露数据及全美托管医疗行业调研资料整理生成，旨在提供结构化的产业分析与红利/困境反转资产估值框架。报告中涉及的盈利预测、EPS 指引、三情景目标价及复利模拟均基于特定假设条件推演，不构成任何证券买卖建议或收益承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n <script>\n // ==========================================\n // 1. 亮色 / 深色模式切换（同步刷新所有 Chart.js 图表）\n // ==========================================\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n // ==========================================\n // 2. 移动端抽屉菜单切换\n // ==========================================\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n // ==========================================\n // 3. 阅读进度条与左侧导航滚动联动高亮\n // ==========================================\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-cncpurple-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-cncpurple-400');\n }\n }\n });\n });\n\n // ==========================================\n // 4. 同行竞争格局矩阵筛选器\n // ==========================================\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-cncpurple-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-cncpurple-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === 'core' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n // ==========================================\n // 5. 森特金（CNC）多维复利与估值重估动态推演器\n // ==========================================\n function updateCompSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n const targetPe = parseFloat(document.getElementById('sim-pe').value);\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n document.getElementById('sim-pe-label').textContent = targetPe.toFixed(1) + 'x (目标退出估值)';\n\n const baseEps2026 = 6.90; // 2026E EPS 中枢\n const g = growthPct / 100;\n\n // 计算期末 EPS\n let endEps = baseEps2026;\n for (let y = 1; y <= years; y++) {\n endEps = endEps * (1 + g);\n }\n\n const impliedPrice = endEps * targetPe;\n const totalVal = principal * (impliedPrice / 35.40); // 相对起始股价 $35.40 的增值\n const totalReturnPct = ((totalVal - principal) / principal) * 100;\n const cagr = (Math.pow(totalVal / principal, 1 / years) - 1) * 100;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(totalVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (${totalReturnPct >= 0 ? '戴维斯双击' : '回调波动'})`;\n document.getElementById('sim-implied-price').textContent = '$' + impliedPrice.toFixed(2);\n document.getElementById('sim-cagr').textContent = cagr.toFixed(1) + '%';\n document.getElementById('sim-end-eps').textContent = '$' + endEps.toFixed(2);\n }\n\n // ==========================================\n // 6. KPI 核查清单状态持久化与计数更新\n // ==========================================\n const KPI_STORAGE_KEY = 'cnc_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {\n // 忽略本地存储权限限制\n }\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {\n // 忽略本地存储权限限制\n }\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n // ==========================================\n // 7. Chart.js 数据可视化初始化与主题自适应\n // ==========================================\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n // 视图 A：2023–2026E 总营收演进与三大板块 ($B)\n const revConfig = {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026E'],\n datasets: [\n {\n label: 'Medicaid 政府托管医疗 ($B)',\n data: [98.5, 102.0, 105.0, 108.0],\n backgroundColor: '#9333EA',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n label: 'Commercial Marketplace ($B)',\n data: [25.0, 28.5, 32.0, 36.0],\n backgroundColor: '#06B6D4',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n label: 'Medicare 及其他业务 ($B)',\n data: [19.0, 20.0, 21.0, 22.0],\n backgroundColor: '#3B82F6',\n borderRadius: 4,\n stack: 'rev'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n }\n }\n },\n scales: {\n x: {\n stacked: true,\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n stacked: true,\n max: 180,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n // 视图 B：会员权重分布 (%)\n const segConfig = {\n type: 'bar',\n data: {\n labels: [\n 'Medicaid (医疗救助会员)',\n 'Commercial Marketplace (商业健康险)',\n 'Medicare (老年医保会员)',\n '其他综合健康服务'\n ],\n datasets: [\n {\n label: '会员比例分布 (%)',\n data: [65, 22, 8, 5],\n backgroundColor: [\n '#9333EA',\n '#06B6D4',\n '#3B82F6',\n '#10B981'\n ],\n borderRadius: 6,\n barThickness: 28\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `会员权重: ${ctx.parsed.y}%`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n max: 80,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue' ? revConfig : segConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnSeg = document.getElementById('btn-chart-seg');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-cncpurple-600 dark:text-cncpurple-400 shadow-sm transition cursor-pointer';\n btnSeg.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2023–2026E 总营收规模与三大保险板块结构';\n subEl.textContent = 'Medicaid 构成核心基本盘，Commercial Marketplace 与 Medicare 稳步扩张';\n } else {\n btnSeg.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-cncpurple-600 dark:text-cncpurple-400 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '核心保险业务线会员权重分布比例';\n subEl.textContent = 'Medicaid 会员占据绝对主导地位，Marketplace 与 Medicare 贡献多元增量';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n 'Medicaid 会员规模与网络',\n '州级政企关系与合规壁垒',\n '多元化收入(Medicaid+ACA)',\n '精细化医保控费与MLR管理',\n '极端低估值安全边际'\n ],\n datasets: [\n {\n label: '森特金 Centene (CNC)',\n data: [9.8, 9.5, 9.2, 8.8, 9.9],\n borderColor: '#9333EA',\n backgroundColor: 'rgba(147, 51, 234, 0.24)',\n pointBackgroundColor: '#9333EA',\n borderWidth: 2.5\n },\n {\n label: '综合医疗险巨头 (UNH/ELV)',\n data: [8.0, 8.2, 9.5, 9.4, 7.0],\n borderColor: '#3B82F6',\n backgroundColor: 'rgba(59, 130, 246, 0.14)',\n pointBackgroundColor: '#3B82F6',\n borderWidth: 1.8\n },\n {\n label: '中小地方性医疗险同行',\n data: [6.0, 6.5, 6.0, 6.2, 8.0],\n borderColor: '#94A3B8',\n backgroundColor: 'rgba(148, 163, 184, 0.12)',\n pointBackgroundColor: '#94A3B8',\n borderWidth: 1.5,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n 'UnitedHealth 联合健康 (UNH)',\n 'Elevance Health (ELV)',\n 'Molina Healthcare (MOH)',\n 'Centene 森特金 (CNC · 极度低估)'\n ],\n datasets: [\n {\n label: '远期市盈率 Forward P/E (x)',\n data: [21.5, 16.8, 14.2, 5.1],\n backgroundColor: [\n '#3B82F6',\n '#06B6D4',\n '#10B981',\n '#9333EA'\n ],\n borderRadius: 6,\n barThickness: 24\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `远期 P/E: ${ctx.parsed.x}x`\n }\n }\n },\n scales: {\n x: {\n max: 25,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + 'x' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '全年总营收 ($B)',\n data: [142.8, 154.0, 158.5, 162.0],\n backgroundColor: 'rgba(147, 51, 234, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后每股收益 EPS ($/股)',\n data: [6.60, 6.75, 6.25, 6.90],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y'\n ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n : `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 100,\n max: 200,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' },\n title: { display: true, text: '全年总营收 ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 4,\n max: 9,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v.toFixed(1) },\n title: { display: true, text: '调整后 EPS ($/股)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateCompSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>\n"};
